test("listDebates filters page metadata after pagination without backfilling", async () => {
  const root = await makeRoot();
  try {
    const unjudged = await debate(root, "debate-z");
    await writeFile(join(unjudged, "final-report.md"), "report");

    const resolved = await debate(root, "debate-y");
    await writeFile(join(resolved, "respondeo.md"), "STATUS: RESOLVED");

    const failed = await debate(root, "debate-x");
    await writeFile(join(failed, "respondeo.md"), "Respondeo turn failed: timeout");
    await writeFile(join(failed, "final-report.md"), "report");

    const secondResolved = await debate(root, "debate-w");
    await writeFile(join(secondResolved, "respondeo.md"), "STATUS: RESOLVED");

    const needsInput = await debate(root, "debate-v");
    await writeFile(join(needsInput, "respondeo.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(needsInput, "final-report.md"), "report");

    const unknown = await debate(root, "debate-u");
    await writeFile(join(unknown, "respondeo.md"), "STATUS: resolved");

    const ids = async (options?: Parameters<typeof listDebates>[1]) =>
      (await listDebates(root, options)).map((entry) => entry.id);
    const full = ["debate-z", "debate-y", "debate-x", "debate-w", "debate-v", "debate-u"];

    assert.deepEqual(await ids(), full);
    assert.deepEqual(await ids({ status: undefined, hasFinalReport: undefined }), full);
    assert.deepEqual(await ids({ status: "unjudged" }), ["debate-z"]);
    assert.deepEqual(await ids({ status: "resolved" }), ["debate-y", "debate-w"]);
    assert.deepEqual(await ids({ status: "needs-input" }), ["debate-v"]);
    assert.deepEqual(await ids({ status: "failed" }), ["debate-x"]);
    assert.deepEqual(await ids({ status: "unknown" }), ["debate-u"]);
    assert.deepEqual(await ids({ hasFinalReport: true }), ["debate-z", "debate-x", "debate-v"]);
    assert.deepEqual(await ids({ hasFinalReport: false }), ["debate-y", "debate-w", "debate-u"]);
    assert.deepEqual(await ids({ status: "needs-input", hasFinalReport: true }), ["debate-v"]);
    assert.deepEqual(await ids({ status: "needs-input", hasFinalReport: false }), []);

    // The page is z/y first; only y is resolved. w is outside this page and cannot fill it.
    assert.deepEqual(await ids({ limit: 2, status: "resolved" }), ["debate-y"]);
    // The offset page is y/x; filtering it still yields y, whereas filter-first would yield w.
    assert.deepEqual(await ids({ offset: 1, limit: 2, status: "resolved" }), ["debate-y"]);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates reads metadata without modifying read-only artifacts", async () => {
  const root = await makeRoot();
  const path = await debate(root, "debate-read-only");
  const transcript = join(path, "debate.md");
  const report = join(path, "final-report.md");
  const determination = join(path, "respondeo.md");
  await writeFile(transcript, "immutable transcript");
  await writeFile(report, "immutable report");
  await writeFile(determination, "STATUS: RESOLVED\nimmutable determination");
  await chmod(transcript, 0o444);
  await chmod(report, 0o444);
  await chmod(determination, 0o444);
  await chmod(path, 0o555);
  const [transcriptBefore, reportBefore] = await Promise.all([lstat(transcript), lstat(report)]);
  try {
    assert.deepEqual(await listDebates(root), [{
      id: "debate-read-only",
      path,
      hasTranscript: true,
      hasFinalReport: true,
      determination: "respondeo.md",
      status: "resolved",
    }]);
    assert.equal(await readFile(transcript, "utf8"), "immutable transcript");
    assert.equal(await readFile(report, "utf8"), "immutable report");
    assert.equal(await readFile(determination, "utf8"), "STATUS: RESOLVED\nimmutable determination");
    assert.equal(await readDebateArtifact(root, "debate-read-only", "transcript"), "immutable transcript");
    assert.equal(await readDebateArtifact(root, "debate-read-only", "final-report"), "immutable report");
    assert.equal(await readDebateArtifact(root, "debate-read-only", "determination"), "STATUS: RESOLVED\nimmutable determination");
    assert.equal((await lstat(determination)).mode & 0o777, 0o444);
    const [transcriptAfter, reportAfter] = await Promise.all([lstat(transcript), lstat(report)]);
    assert.equal(transcriptAfter.mode, transcriptBefore.mode);
    assert.equal(reportAfter.mode, reportBefore.mode);
  } finally {
    await chmod(path, 0o755);
    await rm(root, { recursive: true, force: true });
  }
});

test("classifyDetermination uses only the first nonempty trimmed line", () => {
  assert.equal(classifyDetermination("\n  STATUS: RESOLVED\r\nbody"), "resolved");
  assert.equal(classifyDetermination("\r\n\tSTATUS: NEEDS_INPUT\nbody"), "needs-input");
  assert.equal(classifyDetermination("  Respondeo turn failed: judge timed out\nbody"), "failed");

  for (const text of [
    "",
    " \r\n\t",
    "STATUS:RESOLVED",
    "STATUS:  RESOLVED",
    "STATUS: RESOLVED extra",
    "status: RESOLVED",
    "STATUS: resolved",
    "STATUS: NEEDS_INPUT later",
    "some preamble\nSTATUS: RESOLVED",
    "respondeo turn failed: lower-case prefix",
  ]) assert.equal(classifyDetermination(text), "unknown", text);
});

