import { lstat, readdir } from "node:fs/promises";
import { join, resolve } from "node:path";

export type DebateEntry = {
  id: string;
  path: string;
  hasTranscript: boolean;
  hasFinalReport: boolean;
};

const DEBATE_ID = /^debate-[A-Za-z0-9][A-Za-z0-9._-]*$/;

async function isRegularFile(path: string): Promise<boolean> {
  try {
    // lstat checks the artifact itself without following a file symlink.
    return (await lstat(path)).isFile();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

/** List saved debates using filesystem metadata only; never launch participants. */
export async function listDebates(root: string): Promise<DebateEntry[]> {
  const absoluteRoot = resolve(root);
  let children;
  try {
    children = await readdir(absoluteRoot, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }

  // Dirent.isDirectory() excludes symlinks, including links to directories.
  // IDs are ASCII, so default string sorting is code-point lexical order.
  const ids = children
    .filter((child) => child.isDirectory() && DEBATE_ID.test(child.name))
    .map((child) => child.name)
    .sort();

  return Promise.all(ids.map(async (id) => {
    const path = join(absoluteRoot, id);
    const [hasTranscript, hasFinalReport] = await Promise.all([
      isRegularFile(join(path, "debate.md")),
      isRegularFile(join(path, "final-report.md")),
    ]);
    return { id, path, hasTranscript, hasFinalReport };
  }));
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { chmod, lstat, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
import { listDebates } from "../src/catalog.ts";

async function makeRoot() {
  return mkdtemp(join(process.cwd(), ".disputatio-catalog-"));
}

async function debate(root: string, id: string) {
  const path = join(root, id);
  await mkdir(path, { recursive: true });
  return path;
}

test("listDebates catalogs only immediate matching real directories in code-point order", async () => {
  const root = await makeRoot();
  try {
    await debate(root, "debate-z");
    await debate(root, "debate-Az");
    await debate(root, "debate-10");
    const complete = await debate(root, "debate-aa");
    await writeFile(join(complete, "debate.md"), "transcript");
    await writeFile(join(complete, "final-report.md"), "report");

    await mkdir(join(root, "notes"));
    await debate(join(root, "notes"), "debate-nested");
    await mkdir(join(root, "debate-"));
    await mkdir(join(root, "debate-.hidden"));
    await mkdir(join(root, "Debate-wrong-case"));
    await writeFile(join(root, "debate-file"), "not a directory");

    const entries = await listDebates(root);

    assert.deepEqual(entries, [
      { id: "debate-10", path: join(root, "debate-10"), hasTranscript: false, hasFinalReport: false },
      { id: "debate-Az", path: join(root, "debate-Az"), hasTranscript: false, hasFinalReport: false },
      { id: "debate-aa", path: join(root, "debate-aa"), hasTranscript: true, hasFinalReport: true },
      { id: "debate-z", path: join(root, "debate-z"), hasTranscript: false, hasFinalReport: false },
    ]);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates resolves a relative root and treats a missing root as empty", async () => {
  const root = await makeRoot();
  try {
    await debate(root, "debate-relative");
    const relativeRoot = relative(process.cwd(), root);

    assert.deepEqual(await listDebates(relativeRoot), [
      {
        id: "debate-relative",
        path: resolve(relativeRoot, "debate-relative"),
        hasTranscript: false,
        hasFinalReport: false,
      },
    ]);
    assert.deepEqual(await listDebates(join(root, "not-here")), []);

    const fileRoot = join(root, "not-a-directory");
    await writeFile(fileRoot, "file");
    await assert.rejects(() => listDebates(fileRoot), { code: "ENOTDIR" });
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates reads metadata without modifying read-only artifacts", async () => {
  const root = await makeRoot();
  const path = await debate(root, "debate-read-only");
  const transcript = join(path, "debate.md");
  const report = join(path, "final-report.md");
  await writeFile(transcript, "immutable transcript");
  await writeFile(report, "immutable report");
  await chmod(transcript, 0o444);
  await chmod(report, 0o444);
  await chmod(path, 0o555);
  const [transcriptBefore, reportBefore] = await Promise.all([lstat(transcript), lstat(report)]);
  try {
    assert.deepEqual(await listDebates(root), [{
      id: "debate-read-only",
      path,
      hasTranscript: true,
      hasFinalReport: true,
    }]);
    assert.equal(await readFile(transcript, "utf8"), "immutable transcript");
    assert.equal(await readFile(report, "utf8"), "immutable report");
    const [transcriptAfter, reportAfter] = await Promise.all([lstat(transcript), lstat(report)]);
    assert.equal(transcriptAfter.mode, transcriptBefore.mode);
    assert.equal(reportAfter.mode, reportBefore.mode);
  } finally {
    await chmod(path, 0o755);
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates does not follow directory or artifact symlinks and requires regular artifact files", async () => {
  const root = await makeRoot();
  const outside = await makeRoot();
  try {
    const target = await debate(outside, "source-debate");
    await writeFile(join(target, "debate.md"), "transcript");
    await writeFile(join(target, "final-report.md"), "report");
    await symlink(target, join(root, "debate-linked-directory"), "dir");
    await symlink(join(root, "missing-directory"), join(root, "debate-broken-directory"), "dir");

    const directoryArtifacts = await debate(root, "debate-directory-artifacts");
    await mkdir(join(directoryArtifacts, "debate.md"));
    await mkdir(join(directoryArtifacts, "final-report.md"));

    const symlinkArtifacts = await debate(root, "debate-symlink-artifacts");
    await symlink(join(target, "debate.md"), join(symlinkArtifacts, "debate.md"), "file");
    await symlink(join(root, "missing-report.md"), join(symlinkArtifacts, "final-report.md"), "file");

    const otherSymlinks = await debate(root, "debate-other-symlinks");
    await symlink(join(outside, "missing-transcript.md"), join(otherSymlinks, "debate.md"), "file");
    await symlink(join(target, "final-report.md"), join(otherSymlinks, "final-report.md"), "file");

    assert.deepEqual(await listDebates(root), [
      {
        id: "debate-directory-artifacts",
        path: join(root, "debate-directory-artifacts"),
        hasTranscript: false,
        hasFinalReport: false,
      },
      {
        id: "debate-other-symlinks",
        path: otherSymlinks,
        hasTranscript: false,
        hasFinalReport: false,
      },
      {
        id: "debate-symlink-artifacts",
        path: join(root, "debate-symlink-artifacts"),
        hasTranscript: false,
        hasFinalReport: false,
      },
    ]);
  } finally {
    await rm(root, { recursive: true, force: true });
    await rm(outside, { recursive: true, force: true });
  }
});

