import { test } from "node:test";
import assert from "node:assert/strict";
import { chmod, lstat, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
import { classifyDetermination, listDebates } from "../src/catalog.ts";

async function makeRoot() {
  return mkdtemp(join(process.cwd(), ".disputatio-catalog-"));
}

async function debate(root: string, id: string) {
  const path = join(root, id);
  await mkdir(path, { recursive: true });
  return path;
}

test("listDebates catalogs only immediate matching real directories in descending code-point order", async () => {
  const root = await makeRoot();
  try {
    await debate(root, "debate-z");
    await debate(root, "debate-Az");
    await debate(root, "debate-10");
    const complete = await debate(root, "debate-aa");
    await writeFile(join(complete, "debate.md"), "transcript");
    await writeFile(join(complete, "final-report.md"), "report");

    await mkdir(join(root, "notes"));
    await debate(join(root, "notes"), "debate-nested");
    await mkdir(join(root, "debate-"));
    await mkdir(join(root, "debate-.hidden"));
    await mkdir(join(root, "Debate-wrong-case"));
    await writeFile(join(root, "debate-file"), "not a directory");
    const linkedTarget = await debate(root, "not-a-debate-target");
    await symlink(linkedTarget, join(root, "debate-linked-page"), "dir");

    const entries = await listDebates(root);

    assert.deepEqual(entries, [
      { id: "debate-z", path: join(root, "debate-z"), hasTranscript: false, hasFinalReport: false, determination: null, status: "unjudged" },
      { id: "debate-aa", path: join(root, "debate-aa"), hasTranscript: true, hasFinalReport: true, determination: null, status: "unjudged" },
      { id: "debate-Az", path: join(root, "debate-Az"), hasTranscript: false, hasFinalReport: false, determination: null, status: "unjudged" },
      { id: "debate-10", path: join(root, "debate-10"), hasTranscript: false, hasFinalReport: false, determination: null, status: "unjudged" },
    ]);
    assert.deepEqual(await listDebates(root, undefined), entries);
    assert.deepEqual(await listDebates(root, { offset: undefined, limit: undefined }), entries);
    assert.deepEqual(await listDebates(root, { limit: 2 }), entries.slice(0, 2));
    assert.deepEqual(await listDebates(root, { offset: 1, limit: 2 }), entries.slice(1, 3));
    assert.deepEqual(await listDebates(root, { offset: 2 }), entries.slice(2));
    assert.deepEqual(await listDebates(root, { offset: 0, limit: 0 }), []);
    assert.deepEqual(await listDebates(root, { offset: 99 }), []);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates resolves a relative root and treats a missing root as empty", async () => {
  const root = await makeRoot();
  try {
    await debate(root, "debate-relative");
    const relativeRoot = relative(process.cwd(), root);

    assert.deepEqual(await listDebates(relativeRoot), [
      {
        id: "debate-relative",
        path: resolve(relativeRoot, "debate-relative"),
        hasTranscript: false,
        hasFinalReport: false,
        determination: null,
        status: "unjudged",
      },
    ]);
    assert.deepEqual(await listDebates(join(root, "not-here")), []);

    const fileRoot = join(root, "not-a-directory");
    await writeFile(fileRoot, "file");
    await assert.rejects(() => listDebates(fileRoot), { code: "ENOTDIR" });
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates rejects every invalid page field before looking up the root", async () => {
  const missingRoot = join(process.cwd(), ".disputatio-catalog-missing-root");
  const listWithUnknownOptions = listDebates as unknown as (root: string, options: unknown) => Promise<unknown>;
  const invalidOptions: unknown[] = [
    { offset: -1 }, { limit: -1 },
    { offset: 1.5 }, { limit: 1.5 },
    { offset: Number.NaN }, { limit: Number.NaN },
    { offset: Number.POSITIVE_INFINITY }, { limit: Number.POSITIVE_INFINITY },
    { offset: null }, { limit: null },
    { offset: "1" }, { limit: "1" },
    { offset: true }, { limit: false },
    { offset: {} }, { limit: [] },
    { status: "RESOLVED" }, { status: "not-a-status" },
    { status: null }, { status: true }, { status: {} },
    { hasFinalReport: "true" }, { hasFinalReport: null },
    { hasFinalReport: 1 }, { hasFinalReport: {} },
    { limit: 0, status: "resolved-ish" },
    { limit: 0, hasFinalReport: "false" },
  ];

  for (const options of invalidOptions) {
    await assert.rejects(() => listWithUnknownOptions(missingRoot, options), { code: "INVALID_QUERY" });
  }
});

test("listDebates filters page metadata after pagination without backfilling", async () => {
  const root = await makeRoot();
  try {
    const unjudged = await debate(root, "debate-z");
    await writeFile(join(unjudged, "final-report.md"), "report");

    const resolved = await debate(root, "debate-y");
    await writeFile(join(resolved, "respondeo.md"), "STATUS: RESOLVED");

    const failed = await debate(root, "debate-x");
    await writeFile(join(failed, "respondeo.md"), "Respondeo turn failed: timeout");
    await writeFile(join(failed, "final-report.md"), "report");

    const secondResolved = await debate(root, "debate-w");
    await writeFile(join(secondResolved, "respondeo.md"), "STATUS: RESOLVED");

    const needsInput = await debate(root, "debate-v");
    await writeFile(join(needsInput, "respondeo.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(needsInput, "final-report.md"), "report");

    const unknown = await debate(root, "debate-u");
    await writeFile(join(unknown, "respondeo.md"), "STATUS: resolved");

    const ids = async (options?: Parameters<typeof listDebates>[1]) =>
      (await listDebates(root, options)).map((entry) => entry.id);
    const full = ["debate-z", "debate-y", "debate-x", "debate-w", "debate-v", "debate-u"];

    assert.deepEqual(await ids(), full);
    assert.deepEqual(await ids({ status: undefined, hasFinalReport: undefined }), full);
    assert.deepEqual(await ids({ status: "unjudged" }), ["debate-z"]);
    assert.deepEqual(await ids({ status: "resolved" }), ["debate-y", "debate-w"]);
    assert.deepEqual(await ids({ status: "needs-input" }), ["debate-v"]);
    assert.deepEqual(await ids({ status: "failed" }), ["debate-x"]);
    assert.deepEqual(await ids({ status: "unknown" }), ["debate-u"]);
    assert.deepEqual(await ids({ hasFinalReport: true }), ["debate-z", "debate-x", "debate-v"]);
    assert.deepEqual(await ids({ hasFinalReport: false }), ["debate-y", "debate-w", "debate-u"]);
    assert.deepEqual(await ids({ status: "needs-input", hasFinalReport: true }), ["debate-v"]);
    assert.deepEqual(await ids({ status: "needs-input", hasFinalReport: false }), []);

    // The page is z/y first; only y is resolved. w is outside this page and cannot fill it.
    assert.deepEqual(await ids({ limit: 2, status: "resolved" }), ["debate-y"]);
    // The offset page is y/x; filtering it still yields y, whereas filter-first would yield w.
    assert.deepEqual(await ids({ offset: 1, limit: 2, status: "resolved" }), ["debate-y"]);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("listDebates reads metadata without modifying read-only artifacts", async () => {
  const root = await makeRoot();
  const path = await debate(root, "debate-read-only");
  const transcript = join(path, "debate.md");
  const report = join(path, "final-report.md");
  const determination = join(path, "respondeo.md");
  await writeFile(transcript, "immutable transcript");
  await writeFile(report, "immutable report");
  await writeFile(determination, "STATUS: RESOLVED\nimmutable determination");
  await chmod(transcript, 0o444);
  await chmod(report, 0o444);
  await chmod(determination, 0o444);
  await chmod(path, 0o555);
  const [transcriptBefore, reportBefore] = await Promise.all([lstat(transcript), lstat(report)]);
  try {
    assert.deepEqual(await listDebates(root), [{
      id: "debate-read-only",
      path,
      hasTranscript: true,
      hasFinalReport: true,
      determination: "respondeo.md",
      status: "resolved",
    }]);
    assert.equal(await readFile(transcript, "utf8"), "immutable transcript");
    assert.equal(await readFile(report, "utf8"), "immutable report");
    assert.equal(await readFile(determination, "utf8"), "STATUS: RESOLVED\nimmutable determination");
    assert.equal((await lstat(determination)).mode & 0o777, 0o444);
    const [transcriptAfter, reportAfter] = await Promise.all([lstat(transcript), lstat(report)]);
    assert.equal(transcriptAfter.mode, transcriptBefore.mode);
    assert.equal(reportAfter.mode, reportBefore.mode);
  } finally {
    await chmod(path, 0o755);
    await rm(root, { recursive: true, force: true });
  }
});

test("classifyDetermination uses only the first nonempty trimmed line", () => {
  assert.equal(classifyDetermination("\n  STATUS: RESOLVED\r\nbody"), "resolved");
  assert.equal(classifyDetermination("\r\n\tSTATUS: NEEDS_INPUT\nbody"), "needs-input");
  assert.equal(classifyDetermination("  Respondeo turn failed: judge timed out\nbody"), "failed");

  for (const text of [
    "",
    " \r\n\t",
    "STATUS:RESOLVED",
    "STATUS:  RESOLVED",
    "STATUS: RESOLVED extra",
    "status: RESOLVED",
    "STATUS: resolved",
    "STATUS: NEEDS_INPUT later",
    "some preamble\nSTATUS: RESOLVED",
    "respondeo turn failed: lower-case prefix",
  ]) assert.equal(classifyDetermination(text), "unknown", text);
});

test("listDebates selects the highest regular respondeo version and reports its status", async () => {
  const root = await makeRoot();
  const outside = await makeRoot();
  try {
    const unnumbered = await debate(root, "debate-unnumbered");
    await writeFile(join(unnumbered, "respondeo.md"), "Respondeo turn failed: offline");

    const versions = await debate(root, "debate-versions");
    await writeFile(join(versions, "respondeo.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(versions, "respondeo-2.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(versions, "respondeo-10.md"), "unrecognized");
    await writeFile(join(versions, "respondeo-9007199254740992.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(versions, "respondeo-9007199254740993.md"), "STATUS: RESOLVED");

    const tie = await debate(root, "debate-leading-zero");
    await writeFile(join(tie, "respondeo.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(tie, "respondeo-1.md"), "STATUS: NEEDS_INPUT");
    await writeFile(join(tie, "respondeo-01.md"), "STATUS: RESOLVED");

    const needsInput = await debate(root, "debate-needs-input");
    await writeFile(join(needsInput, "respondeo.md"), "STATUS: NEEDS_INPUT");

    const unknown = await debate(root, "debate-unknown");
    await writeFile(join(unknown, "respondeo.md"), "STATUS: resolved");

    const ignored = await debate(root, "debate-ignored-determinations");
    await writeFile(join(ignored, "respondeo-0.md"), "STATUS: RESOLVED");
    await writeFile(join(ignored, "respondeo--1.md"), "STATUS: RESOLVED");
    await writeFile(join(ignored, "respondeo-nope.md"), "STATUS: RESOLVED");
    await mkdir(join(ignored, "respondeo-999.md"));
    const outsideDetermination = join(outside, "respondeo-1000.md");
    await writeFile(outsideDetermination, "STATUS: RESOLVED");
    await symlink(outsideDetermination, join(ignored, "respondeo-1000.md"), "file");
    await symlink(join(outside, "missing.md"), join(ignored, "respondeo-1001.md"), "file");

    const numeric = await debate(root, "debate-numeric");
    await writeFile(join(numeric, "respondeo-2.md"), "STATUS: RESOLVED");
    await writeFile(join(numeric, "respondeo-10.md"), "STATUS: NEEDS_INPUT");
    await symlink(outsideDetermination, join(numeric, "respondeo-11.md"), "file");
    await mkdir(join(numeric, "respondeo-12.md"));

    assert.deepEqual(await listDebates(root), [
      { id: "debate-versions", path: versions, hasTranscript: false, hasFinalReport: false, determination: "respondeo-9007199254740993.md", status: "resolved" },
      { id: "debate-unnumbered", path: unnumbered, hasTranscript: false, hasFinalReport: false, determination: "respondeo.md", status: "failed" },
      { id: "debate-unknown", path: unknown, hasTranscript: false, hasFinalReport: false, determination: "respondeo.md", status: "unknown" },
      { id: "debate-numeric", path: numeric, hasTranscript: false, hasFinalReport: false, determination: "respondeo-10.md", status: "needs-input" },
      { id: "debate-needs-input", path: needsInput, hasTranscript: false, hasFinalReport: false, determination: "respondeo.md", status: "needs-input" },
      { id: "debate-leading-zero", path: tie, hasTranscript: false, hasFinalReport: false, determination: "respondeo-01.md", status: "resolved" },
      { id: "debate-ignored-determinations", path: ignored, hasTranscript: false, hasFinalReport: false, determination: null, status: "unjudged" },
    ]);
  } finally {
    await rm(root, { recursive: true, force: true });
    await rm(outside, { recursive: true, force: true });
  }
});

test("listDebates does not follow directory or artifact symlinks and requires regular artifact files", async () => {
  const root = await makeRoot();
  const outside = await makeRoot();
  try {
    const target = await debate(outside, "source-debate");
    await writeFile(join(target, "debate.md"), "transcript");
    await writeFile(join(target, "final-report.md"), "report");
    await symlink(target, join(root, "debate-linked-directory"), "dir");
    await symlink(join(root, "missing-directory"), join(root, "debate-broken-directory"), "dir");

    const directoryArtifacts = await debate(root, "debate-directory-artifacts");
    await mkdir(join(directoryArtifacts, "debate.md"));
    await mkdir(join(directoryArtifacts, "final-report.md"));

    const symlinkArtifacts = await debate(root, "debate-symlink-artifacts");
    await symlink(join(target, "debate.md"), join(symlinkArtifacts, "debate.md"), "file");
    await symlink(join(root, "missing-report.md"), join(symlinkArtifacts, "final-report.md"), "file");

    const otherSymlinks = await debate(root, "debate-other-symlinks");
    await symlink(join(outside, "missing-transcript.md"), join(otherSymlinks, "debate.md"), "file");
    await symlink(join(target, "final-report.md"), join(otherSymlinks, "final-report.md"), "file");

    assert.deepEqual(await listDebates(root), [
      {
        id: "debate-symlink-artifacts",
        path: join(root, "debate-symlink-artifacts"),
        hasTranscript: false,
        hasFinalReport: false,
        determination: null,
        status: "unjudged",
      },
      {
        id: "debate-other-symlinks",
        path: otherSymlinks,
        hasTranscript: false,
        hasFinalReport: false,
        determination: null,
        status: "unjudged",
      },
      {
        id: "debate-directory-artifacts",
        path: join(root, "debate-directory-artifacts"),
        hasTranscript: false,
        hasFinalReport: false,
        determination: null,
        status: "unjudged",
      },
    ]);
  } finally {
    await rm(root, { recursive: true, force: true });
    await rm(outside, { recursive: true, force: true });
  }
});

