#!/usr/bin/env node
// Standalone, read-only catalog entry point: no debate-engine or participant imports.
import { listDebates, type ListDebatesOptions } from "./catalog.ts";

const FLAGS = new Set(["--root", "--status", "--has-final-report", "--offset", "--limit"]);

function invalidQuery(message: string): never {
  throw Object.assign(new Error(message), { code: "INVALID_QUERY" });
}

function parseArguments(args: string[]): { root: string; options: ListDebatesOptions } {
  let root: string | undefined;
  const options: ListDebatesOptions = {};
  const seen = new Set<string>();
  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    if (!FLAGS.has(flag)) invalidQuery(`Unknown argument: ${flag}`);
    if (seen.has(flag)) invalidQuery(`Duplicate flag: ${flag}`);
    seen.add(flag);
    const value = args[++i];
    if (value === undefined || value === "" || value.startsWith("--")) {
      invalidQuery(`Missing value for ${flag}`);
    }

    switch (flag) {
      case "--root":
        root = value;
        break;
      case "--status":
        // listDebates validates the status before accessing the filesystem.
        options.status = value as ListDebatesOptions["status"];
        break;
      case "--has-final-report":
        if (value !== "yes" && value !== "no") invalidQuery(`${flag} must be yes or no`);
        options.hasFinalReport = value === "yes";
        break;
      case "--offset":
      case "--limit": {
        const number = Number(value);
        if (/\D/.test(value) || !Number.isInteger(number)) {
          invalidQuery(`${flag} must be a nonnegative integer`);
        }
        options[flag === "--offset" ? "offset" : "limit"] = number;
        break;
      }
    }
  }
  if (root === undefined) invalidQuery("Missing required --root DIRECTORY");
  return { root, options };
}

try {
  const { root, options } = parseArguments(process.argv.slice(2));
  const entries = await listDebates(root, options);
  // Emit nothing to stdout until argument validation and the full scan succeed.
  console.log(JSON.stringify(entries));
} catch (error) {
  const code = (error as NodeJS.ErrnoException).code ?? "CATALOG_ERROR";
  const message = error instanceof Error ? error.message : String(error);
  console.error(`${code}: ${message}`);
  process.exitCode = 1;
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { promisify } from "node:util";
import { join } from "node:path";

const execFileAsync = promisify(execFile);
const cliPath = join(process.cwd(), "src", "catalog-cli.ts");

type CliResult = { code: number; stdout: string; stderr: string };

async function runCli(args: string[]): Promise<CliResult> {
  try {
    const { stdout, stderr } = await execFileAsync(process.execPath, [cliPath, ...args], {
      cwd: process.cwd(),
    });
    return { code: 0, stdout, stderr };
  } catch (error) {
    const result = error as NodeJS.ErrnoException & { stdout?: string; stderr?: string };
    return { code: typeof result.code === "number" ? result.code : 1, stdout: result.stdout ?? "", stderr: result.stderr ?? "" };
  }
}

async function makeRoot() {
  return mkdtemp(join(process.cwd(), ".disputatio-catalog-cli-"));
}

async function debate(root: string, id: string) {
  const path = join(root, id);
  await mkdir(path, { recursive: true });
  return path;
}

